import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int t = Integer.parseInt(st.nextToken()); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { st = new StringTokenizer(br.readLine()); int a = Integer.parseInt(st.nextToken()); int b = Integer.parseInt(st.nextToken()); int s = a + b; int minMoves = Integer.MAX_VALUE; for (int bNew = 1; bNew < s; bNew++) { int aNew = s - bNew; if (aNew % bNew == 0) { int moves = Math.abs(a - aNew); if (moves < minMoves) { minMoves = moves; } } } out.println(minMoves); } out.flush(); out.close(); } }